window.MOTIF_CATALOG_CHUNKS[64]={"cards":[{"id":"MEJE-KW-006513","row_version":1,"title":"맥락을 거부하는 부조리 만화","original":"Dada Comics","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"만화가 이어지는 이야기나 뜻풀이보다 비논리적 장면과 무관한 농담을 반복한다. 이해하려 할수록 멀어지는 형식 자체가 웃음의 바탕이다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-006513/index.html"},{"id":"MEJE-KW-006514","row_version":2,"title":"약속한 날 다시 나타나지 않은 부모","original":"Daddy Didn't Show","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"오랜 부재 뒤 돌아온 부모가 자녀와의 중요한 약속을 또 지키지 않는다. 재회에 걸었던 희망이 두 번째 실망으로 바뀐다. 돌아온 부모가 중요한 날 또 실망을 준다면 그가 내세운 떠난 부모에게 있었다는 보호의 이유도 관계를 회복시키지 못할 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006514/index.html"},{"id":"MEJE-KW-006515","row_version":1,"title":"친부를 확인하는 유전자 검사","original":"Daddy DNA Test","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가족 관계에 의문이 생기자 검사 결과로 아이의 생물학적 아버지를 가린다. 확인된 사실과 함께 살아온 관계가 서로 다를 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006515/index.html"},{"id":"MEJE-KW-006516","row_version":1,"title":"떠난 부모에게 있었다는 보호의 이유","original":"Daddy Had a Good Reason for Abandoning You","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"오랫동안 아이 곁에 없던 부모가 돌아와 떠날 수밖에 없었다고 설명한다. 버림받았다는 기억과 보호하려던 선택 사이에서 관계를 다시 판단한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006516/index.html"},{"id":"MEJE-KW-006517","row_version":1,"title":"아버지와 유난히 가까운 딸","original":"Daddy's Girl","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"딸이 아버지를 동경하고 자주 의지하며 두 사람이 특별히 가까운 관계를 이룬다. 가족 안의 다른 관계와 대비되기도 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006517/index.html"},{"id":"MEJE-KW-006518","row_version":1,"title":"악당 집안의 딸·조카·손녀","original":"Daddy's Little Villain","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"악당의 딸, 조카, 손녀 같은 친족이 가족의 범죄적 영향 아래에서 악역으로 등장한다. 세력을 이어받을 수도 있지만 후계자일 필요는 없다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006518/index.html"},{"id":"MEJE-KW-006519","row_version":1,"title":"아버지는 요리를 못한다는 관습","original":"Dads Can't Cook","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아버지가 집에서 음식을 만들면 간단한 것조차 서툴러 가족을 곤란하게 한다고 그리는 고정관념이다. 성별에 따른 가사 능력의 차이를 사실처럼 전제하는 표현이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006519/index.html"},{"id":"MEJE-KW-006520","row_version":2,"title":"전쟁에 나가 부재한 부모","original":"Dad's Off Fighting in the War","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"부모가 전쟁터에 있어 자녀 곁에 오래 머물지 못한다. 가족의 부재가 죽음으로 확정되지 않은 채 기다림과 불안을 남긴다. 전쟁터에서 돌아온 아버지가 가족 앞에 다시 서면 참전 경험을 내세우는 아버지의 유형으로 이어질 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006520/index.html"},{"id":"MEJE-KW-006521","row_version":1,"title":"참전 경험을 내세우는 아버지","original":"Dad the Veteran","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"가족 앞에서는 평범해 보이던 아버지가 군 복무 경험을 들며 뜻밖의 강단을 보인다. 과거의 전쟁이 현재의 가족 역할에 드러난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006521/index.html"},{"id":"MEJE-KW-006522","row_version":1,"title":"기자를 다그치는 신문 편집장","original":"Da Editor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"편집장이 기자들의 독단을 큰소리로 꾸짖으면서도 취재의 자유를 지키려 한다. 엄격한 상관과 언론의 방패가 한 인물에 겹친다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006522/index.html"},{"id":"MEJE-KW-006523","row_version":1,"title":"바다 괴물로 바뀐 다곤 신","original":"Dagon of the Depths","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"고대의 번영 신 다곤을 후대 작품이 물속에 사는 괴물로 다시 그린다. 원래 신화와 현대의 공포 이미지가 어긋나는 전승 변형이다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006523/index.html"},{"id":"MEJE-KW-006524","row_version":1,"title":"높이 쌓은 거대한 샌드위치","original":"Dagwood Sandwich","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"여러 재료를 한없이 쌓아 한입에 먹기 어려울 만큼 커진 샌드위치다. 음식의 크기가 먹는 사람의 욕심과 만화적 과장을 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006524/index.html"},{"id":"MEJE-KW-006525","row_version":2,"title":"우아하면서도 효과적인 전투 방식","original":"Dainty Combat","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 효과적으로 싸우면서 동작은 우아하고 미적으로 정돈된 방식으로 그려진다. 특히 여성 전투력을 성별화된 미적 기준에 맞추는 관습으로 쓰일 수 있다. 여성의 몸짓을 아름다움에 맞추는 전투 연출은 무용수의 힘을 지우는 발레 무용수를 연약하게 그리기와 표현상의 편견을 공유한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006525/index.html"},{"id":"MEJE-KW-006526","row_version":1,"title":"발레 무용수를 연약하게 그리기","original":"Dainty Little Ballet Dancers","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"발레 무용수를 늘 가볍고 섬세한 인물로만 묘사한다. 실제 춤에 필요한 힘과 훈련을 지우는 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006526/index.html"},{"id":"MEJE-KW-006527","row_version":2,"title":"공격받은 거점의 피해 수습","original":"Damage Control","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"함선이나 도시가 사고 또는 공격으로 손상되자 남은 이들이 구조와 복구에 나선다. 진행 중인 위기 속에서 공동체의 지속 가능성을 지키는 행동이다. 게임에서 건물의 피해를 보여 주는 불꽃은 손상된 게임 대상의 연기·불꽃 표시라는 시각 규칙으로 나타난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006527/index.html"},{"id":"MEJE-KW-006528","row_version":1,"title":"대상에 따라 달라지는 피해 판정","original":"Damage Discrimination","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 같은 위험이 플레이어와 아군, 적에게 서로 다르게 작용한다. 피해 규칙의 예외가 편의와 불공정함을 동시에 드러낸다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006528/index.html"},{"id":"MEJE-KW-006529","row_version":1,"title":"되살아났지만 손상된 영혼","original":"Damaged Soul","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"죽음에서 돌아온 인물의 몸은 회복됐지만 영혼이나 마음은 이전과 달라진다. 재회의 기쁨과 되돌릴 수 없는 변화가 충돌한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006529/index.html"},{"id":"MEJE-KW-006530","row_version":1,"title":"받는 피해를 늘리는 약화 효과","original":"Damage-Increasing Debuff","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 상태 이상이 대상의 방어를 낮추거나 공격에 대한 취약성을 높인다. 같은 공격도 더 큰 피해가 되는 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006530/index.html"},{"id":"MEJE-KW-006531","row_version":1,"title":"손상된 게임 대상의 연기·불꽃 표시","original":"Damage Is Fire","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략·차량 전투 게임에서 건물이나 차량이 손상되면 연기 또는 불꽃으로 피해 상태를 나타낸다. 시각 효과가 추가 피해가 아니라 체력 정보를 알리는 기호로 쓰일 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006531/index.html"},{"id":"MEJE-KW-006532","row_version":2,"title":"시간에 따라 누적되는 피해","original":"Damage Over Time","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 공격 한 번으로 끝나지 않고 일정한 간격마다 피해가 반복되는 상태 효과. 지속 시간이 길수록 작은 피해가 큰 부담으로 쌓인다. 반복 피해를 줄이는 방어 수치를 둔다면 피해량 감소 규칙과 함께 작동한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006532/index.html"},{"id":"MEJE-KW-006533","row_version":1,"title":"좀처럼 파손되지 않는 탈것","original":"Damage-Proof Vehicle","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"추격이나 충돌을 겪은 차와 비행기가 이야기상 필요할 때만 손상된다. 사건의 규모보다 탈것의 역할이 내구성을 결정하는 표현 관습이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006533/index.html"},{"id":"MEJE-KW-006534","row_version":2,"title":"피해량 감소 규칙","original":"Damage Reduction","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 들어온 공격의 일정 부분을 방어 수치가 먼저 덜어 내고 남은 양만 피해로 계산한다. 같은 공격도 방어력에 따라 결과가 달라진다. 피해 종류마다 다른 방어 수치를 적용하면 피해 종류별로 나누는 게임 규칙의 구분이 중요해진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006534/index.html"},{"id":"MEJE-KW-006535","row_version":2,"title":"공격·회복·방어의 삼인 역할","original":"Damager, Healer, Tank","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"팀 전투에서 피해를 주는 역할, 아군을 회복하는 역할, 공격을 받아 내는 역할을 나눠 협력한다. 각자의 강점이 서로의 빈틈을 메운다. 공격 역할이 맞서는 적의 체력만 크게 늘리면 체력만 높은 보스과 긴 소모전이 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006535/index.html"},{"id":"MEJE-KW-006536","row_version":1,"title":"체력만 높은 보스","original":"Damage-Sponge Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"다른 적보다 체력과 공격력은 훨씬 높지만 특별한 행동 변화는 적은 게임 보스. 전투가 긴 소모전으로 이어진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006536/index.html"},{"id":"MEJE-KW-006537","row_version":1,"title":"피해 종류별로 나누는 게임 규칙","original":"Damage Typing","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 충격·화상 등 피해를 서로 다른 종류로 나눠 별도 저항이나 회복을 적용한다. 하나의 체력 수치에 다양한 상처의 차이를 반영한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006537/index.html"},{"id":"MEJE-KW-006538","row_version":1,"title":"사건을 들고 찾아온 여성 의뢰인","original":"Dame with a Case","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"하드보일드 탐정 앞에 인상적인 여성 의뢰인이 나타나 비밀스러운 사건을 맡긴다. 방문 자체가 탐정 서사의 출발 신호가 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006538/index.html"},{"id":"MEJE-KW-006539","row_version":1,"title":"평판 나쁜 이의 칭찬이 부른 역효과","original":"Damned by a Fool's Praise","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"판단을 믿지 않는 인물이 어떤 대상을 극찬하면 주변은 오히려 질이 낮다는 신호로 받아들인다. 칭찬하는 사람의 평판이 평가의 뜻을 뒤집는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006539/index.html"},{"id":"MEJE-KW-006540","row_version":1,"title":"미지근한 칭찬으로 드러내는 혹평","original":"Damned by Faint Praise","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"좋게 말해야 하는 자리에서 사소한 장점만 겨우 집어 칭찬한다. 빠진 칭찬의 크기가 실제 평가를 암시한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006540/index.html"},{"id":"MEJE-KW-006541","row_version":1,"title":"범죄자의 삶을 멋지게 포장하기","original":"Damn, It Feels Good to Be a Gangster!","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"범죄 조직의 돈과 권력과 자유를 매혹적인 생활처럼 보여준다. 화려한 연출은 범죄가 남기는 피해와 긴장 관계를 이룬다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006541/index.html"},{"id":"MEJE-KW-006542","row_version":1,"title":"손에 밴 조작 때문에 실수하기","original":"Damn You, Muscle Memory!","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"다른 게임에서 익힌 버튼 배열을 무심코 적용해 의도와 다른 행동을 한다. 오래 굳은 습관이 새 규칙에 적응하는 걸 방해한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006542/index.html"},{"id":"MEJE-KW-006543","row_version":2,"title":"구출받는 여성 인물이 조력하다","original":"Damsel Assist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험에 처해 구조를 기다리는 여성 인물도 구조 과정에서 정보나 능력으로 도움을 준다. 보호받는 역할과 능동적 기여가 함께 나타난다. 구조를 기다리는 인물이 직접 도움을 줄 때 구출이 필요한 여성 인물의 수동적인 역할을 변형한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006543/index.html"},{"id":"MEJE-KW-006544","row_version":2,"title":"모험을 이끄는 여성 안내자","original":"Damsel Errant","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기사도 이야기에서 여성이 모험의 목적지와 도움이 필요한 사람을 알고 기사에게 길을 제시한다. 구조를 기다리는 인물과 다른 안내자 역할이다. 모험의 길을 알려 주는 안내자는 위험에 놓여 구조를 기다리는 구출이 필요한 여성 인물과 다른 역할이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006544/index.html"},{"id":"MEJE-KW-006545","row_version":2,"title":"위기에 몰린 여성이 반격 후 달아나다","original":"Damsel Fight-and-Flight Response","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"궁지에 몰린 여성 인물이 위협하는 상대에게 순간적으로 반격한 뒤 탈출을 시도한다. 잠깐 얻은 틈을 벗어날 기회로 쓰는 장면이다. 반격으로 얻은 틈에 끝내 혼자 탈출하면 스스로 위기에서 벗어나는 여성 인물의 결말이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006545/index.html"},{"id":"MEJE-KW-006546","row_version":2,"title":"구출이 필요한 여성 인물","original":"Damsel in Distress","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"여성 인물이 위험에 빠지고 다른 인물들이 그를 구하려는 목표로 움직인다. 구조받는 사람이 이야기의 동기가 되지만 역할이 그 사람의 전부일 필요는 없다. 구조의 대상이 스스로 해결에 나서면 스스로 위기에서 벗어나는 여성 인물으로 역할이 바뀐다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006546/index.html"},{"id":"MEJE-KW-006547","row_version":1,"title":"스스로 위기에서 벗어나는 여성 인물","original":"Damsel out of Distress","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"구조자가 오기 전에 위험에 놓인 여성 인물이 자신의 판단과 행동으로 탈출한다. 구출 대상이라는 기대가 능동적인 해결로 바뀐다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006547/index.html"},{"id":"MEJE-KW-006548","row_version":2,"title":"반복 구출 때문에 미움받는 인물","original":"Damsel Scrappy","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"늘 위험에 빠져 다른 인물의 도움을 받아야 하는 배역이 관객에게 부담스러운 존재로 받아들여진다. 문제는 위험 자체보다 인물에게 주어진 역할의 반복일 수 있다. 구출 장면이 거듭되며 관객의 반감을 사는 인물은 구출이 필요한 여성 인물의 반복된 사용에서 생긴다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006548/index.html"},{"id":"MEJE-KW-006549","row_version":1,"title":"춤추며 싸우는 전투원","original":"Dance Battler","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 춤의 리듬과 몸놀림을 전투 동작에 섞는다. 우아한 움직임이 상대의 예측을 흐리고 인물의 개성을 드러낸다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006549/index.html"},{"id":"MEJE-KW-006550","row_version":2,"title":"춤을 사랑하는 인물","original":"Dance Enthusiast","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"직업이나 의무와 관계없이 자주 춤을 추고 그 시간을 즐기는 인물. 춤은 기분과 삶의 태도를 표현하는 일상의 언어가 된다. 춤을 좋아하는 인물이 주변 사람도 끌어들이면 한 사람씩 이어지는 춤의 행렬이 시작된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006550/index.html"},{"id":"MEJE-KW-006551","row_version":2,"title":"한 사람씩 이어지는 춤의 행렬","original":"Dance Line","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"춤추던 사람이 다른 사람을 끌어들이고 그 사람이 다시 다음 사람을 부르며 줄이 길어진다. 개인의 즐거움이 집단의 춤으로 번진다. 한 사람씩 늘어난 춤이 마지막에 전체 출연진의 축제가 되면 모두 함께 춤추며 끝내기과 이어진다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006551/index.html"},{"id":"MEJE-KW-006552","row_version":2,"title":"절망을 달래는 격한 춤","original":"Dance of Despair","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"해결하기 어려운 고통을 겪는 인물이 다른 사람들 앞에서 격렬하게 춤추며 괴로움을 감추거나 표현한다. 말로 꺼내지 못한 감정이 몸의 리듬으로 터져 나온다. 혼자 추는 춤이라도 절망을 버티려는 몸짓이라면 홀로 춤추는 장면과 정서가 달라진다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006552/index.html"},{"id":"MEJE-KW-006553","row_version":2,"title":"춤으로 겨루는 대결","original":"Dance-Off","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"두 사람이나 집단이 춤 실력과 표현력으로 서로에게 도전한다. 싸움의 긴장이 몸짓과 관중의 반응으로 옮겨 간다. 춤 대결은 무도회장의 최고 춤꾼이 다른 경쟁자의 도전을 받는 무대가 된다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006553/index.html"},{"id":"MEJE-KW-006554","row_version":2,"title":"춤추며 시작되는 로맨스","original":"Dance of Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가까이 춤추는 동안 두 인물이 전에 없던 설렘이나 호감을 깨닫는다. 함께 맞춘 발걸음이 관계의 변화를 이끈다. 두 인물의 가까운 춤은 사교 무도회의 사회적 공간에서 자주 일어난다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006554/index.html"},{"id":"MEJE-KW-006555","row_version":2,"title":"모두 함께 춤추며 끝내기","original":"Dance Party Ending","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"큰 갈등이 해결된 뒤 주요 인물들이 한자리에 모여 춤으로 기쁨을 나눈다. 공동의 움직임이 이야기의 밝은 마침표가 된다. 마지막 축제에 사람들을 한 명씩 합류시키면 한 사람씩 이어지는 춤의 행렬의 구도를 쓸 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006555/index.html"},{"id":"MEJE-KW-006556","row_version":1,"title":"댄스 펑크","original":"Dance-Punk","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"펑크와 포스트펑크의 거친 질감에 춤추기 쉬운 리듬을 결합한 음악 양식. 기타의 긴장감과 반복되는 박자가 함께 움직인다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006556/index.html"},{"id":"MEJE-KW-006557","row_version":2,"title":"사교 무도회","original":"Dances and Balls","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"사람들이 춤과 대화를 위해 모이는 행사가 연애·소문·권력 관계의 무대가 된다. 초대와 복장이 그 사회의 신분 질서도 드러낸다. 무도회의 춤이 관계를 바꿀 때 춤추며 시작되는 로맨스이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006557/index.html"},{"id":"MEJE-KW-006558","row_version":2,"title":"노래가 퍼뜨리는 새 춤","original":"Dance Sensation","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"쉽게 따라 할 동작을 알려 주는 노래가 유행해 많은 사람이 같은 춤을 춘다. 음악과 몸짓이 함께 대중적 현상이 된다. 새로운 춤이 유행하면 많은 사람이 따라 추는 한 사람씩 이어지는 춤의 행렬을 만들기 쉽다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006558/index.html"},{"id":"MEJE-KW-006559","row_version":1,"title":"기술적 신기함만으로 주목받는 작품","original":"Dancing Bear","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"완성도보다 제작 방식의 특이함이나 최초의 성취 때문에 관객을 끄는 작품. 신기함이 익숙해지면 평가의 기준도 달라진다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006559/index.html"},{"id":"MEJE-KW-006560","row_version":1,"title":"진지하게 다뤄지는 춤","original":"Dancing Is Serious Business","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"춤을 가벼운 여흥이 아니라 중요한 목표나 감정의 표현처럼 다루거나 심각한 줄거리 한가운데 예상 밖의 춤을 넣는다. 몸의 움직임에 큰 서사적 무게가 실린다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006560/index.html"},{"id":"MEJE-KW-006561","row_version":1,"title":"악역 부하들이 추는 엔딩 춤","original":"Dancing Mook Credits","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"본편에서 주인공과 맞섰던 작은 적들이 엔딩 크레딧에서 함께 춤춘다. 갈등이 끝난 뒤 가벼운 뒤풀이를 보여준다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006561/index.html"},{"id":"MEJE-KW-006562","row_version":2,"title":"움직이는 탈것에서 펼치는 노래춤","original":"Dancing on a Bus","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"버스나 기차처럼 이동 중인 탈것 안팎에서 인물이 노래하고 춤춘다. 여행의 움직임이 감정의 고조와 집단 공연을 받쳐 준다. 이동하는 탈것의 승객이 차례로 노래와 춤에 합류하면 한 사람씩 이어지는 춤의 행렬이 형성된다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006562/index.html"},{"id":"MEJE-KW-006563","row_version":1,"title":"무도회장의 최고 춤꾼","original":"Dancing Royalty","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소에는 평범해 보이는 인물이 춤판에 들어서면 모두의 주목을 받는다. 숨겨진 실력이 공간 안의 지위를 바꾼다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006563/index.html"},{"id":"MEJE-KW-006564","row_version":1,"title":"주제가 영상의 단체 춤","original":"Dancing Theme","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품의 시작이나 끝을 알리는 영상에서 등장인물들이 음악에 맞춰 춤춘다. 반복해서 보는 춤이 밝은 분위기와 인물 구성을 알린다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006564/index.html"},{"id":"MEJE-KW-006565","row_version":1,"title":"홀로 춤추는 장면","original":"Dancing with Myself","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"주변에 함께 춤출 사람이 없어도 인물이 혼자 음악에 몸을 맡긴다. 같은 행동이 자유로움이나 외로움으로 읽힐 수 있다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006565/index.html"},{"id":"MEJE-KW-006566","row_version":1,"title":"문명 붕괴를 기뻐하며 춤추다","original":"Dancin' in the Ruins","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"폐허가 된 세계에서 인물이 사회의 몰락을 해방처럼 받아들이며 춤춘다. 다른 이들의 재난과 인물의 기쁨이 불편하게 어긋난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006566/index.html"},{"id":"MEJE-KW-006567","row_version":1,"title":"낯가리지만 가까운 사람에게 다정한 인물","original":"Dandere","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소에는 말수가 적고 감정을 숨기지만 신뢰하는 사람 앞에서는 활발하고 다정해진다. 조용함이 무관심이 아니라 수줍음에서 나왔음이 드러난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006567/index.html"},{"id":"MEJE-KW-006568","row_version":1,"title":"위험 속에서도 차분한 조종사 말투","original":"Danger Deadpan","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"큰 위기에도 조종사가 무전이나 안내 방송에서 낮고 침착한 어조를 유지한다. 말의 평온함과 상황의 심각함이 대비된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006568/index.html"},{"id":"MEJE-KW-006569","row_version":1,"title":"은하 중심부의 위험 지대","original":"Danger in the Galactic Core","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"우주 이야기에서 은하 중심을 접근하기 어렵고 위협이 도사리는 장소로 설정한다. 넓은 우주의 중심이 탐험의 미지와 공포를 모은다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006569/index.html"},{"id":"MEJE-KW-006570","row_version":2,"title":"열여섯 번째 생일의 위기","original":"Dangerous 16th Birthday","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"열여섯 번째 생일을 맞은 인물에게 힘의 각성이나 오래된 운명의 위협이 닥친다. 축하할 날이 성장의 시험으로 바뀐다. 생일에 깨어난 능력을 쓰는 일이 큰 대가를 치러야 한다면 대가가 큰 금지 기술의 선택이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006570/index.html"},{"id":"MEJE-KW-006571","row_version":1,"title":"휘두른 무기가 뒤의 사람까지 위협하다","original":"Dangerous Backswing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"앞의 상대를 향해 큰 무기를 휘두른 인물이 뒤쪽의 다른 사람에게도 뜻밖의 피해를 준다. 공격 범위의 실수가 전투의 혼란을 키운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006571/index.html"},{"id":"MEJE-KW-006572","row_version":1,"title":"절벽 옆 위험한 길","original":"Dangerous Clifftop Road","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"가파른 낭떠러지 옆으로 이어진 좁은 길을 차량이 지난다. 조그만 실수도 큰 사고로 이어질 수 있다는 공간적 긴장이 생긴다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006572/index.html"},{"id":"MEJE-KW-006573","row_version":1,"title":"위험한 탈영병으로 그리기","original":"Dangerous Deserter","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"붙잡히면 큰 벌을 받는 탈영병이 궁지에 몰려 다른 사람에게도 위협적일 것처럼 그려진다. 실제 탈영 경험 전체를 단정하지 않는 허구 속 인물상이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006573/index.html"},{"id":"MEJE-KW-006574","row_version":1,"title":"버린 위험한 물건이 돌아오다","original":"Dangerous Device Disposal Debacle","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"위협적인 장치나 물건을 버려 문제를 끝냈다고 생각했지만 다른 사람이 주워 다시 사건에 끌어들인다. 처분이 해결이 되지 않는 이야기 장치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006574/index.html"},{"id":"MEJE-KW-006575","row_version":1,"title":"위험의 신호로 취급되는 졸음","original":"Dangerous Drowsiness","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품에서 평범해 보이는 피로감이 곧 심각한 질환이나 초자연적 영향의 징후로 해석된다. 일상적 증상을 위기의 전조로 쓰는 허구적 관습이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006575/index.html"},{"id":"MEJE-KW-006576","row_version":2,"title":"대가가 큰 금지 기술","original":"Dangerous Forbidden Technique","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"강한 효과를 내지만 사용자에게 큰 손상이나 위험을 남기는 비장의 기술. 힘을 쓸지 말지의 선택이 절박함을 보여준다. 금지 기술이 서로 맞지 않는 두 힘을 결합해 위험해진다면 섞으면 위험한 초자연 물질의 규칙을 따른다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006576/index.html"},{"id":"MEJE-KW-006577","row_version":1,"title":"분노를 담은 짧은 되물음","original":"Dangerous Interrogative","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"상대의 말에 인물이 짧게 되묻지만 어조에서 위험한 분노가 느껴진다. 단순한 질문이 다가올 충돌의 경고가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006577/index.html"},{"id":"MEJE-KW-006578","row_version":1,"title":"도망 직전 떨어뜨린 열쇠","original":"Dangerous Key Fumble","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위협을 피해 잠긴 문을 열려던 인물이 급한 순간 열쇠를 놓친다. 작고 흔한 물건 하나가 탈출 시간을 빼앗는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006578/index.html"},{"id":"MEJE-KW-006579","row_version":1,"title":"이발사의 면도가 위협이 되기","original":"Dangerously Close Shave","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"이발사가 손님을 면도하는 평범한 장면에서 날카로운 도구가 갑자기 위험하게 느껴진다. 작은 상처부터 심각한 위협까지 돌봄의 서비스가 긴장으로 바뀐다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006579/index.html"},{"id":"MEJE-KW-006580","row_version":1,"title":"한눈팔다 위험을 놓치다","original":"Dangerously Distracted","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 다른 광경에 정신을 빼앗겨 앞의 장애물이나 위협을 늦게 알아챈다. 시선이 빗나간 짧은 시간이 사고를 부른다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006580/index.html"},{"id":"MEJE-KW-006581","row_version":1,"title":"화려하지만 위험한 장소","original":"Dangerously Garish Environment","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"빛나는 색과 아름다운 풍경이 방문객을 끌지만 그 안에는 포식자나 음모가 숨어 있다. 아름다움이 안전을 보장하지 않는 배경이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006581/index.html"},{"id":"MEJE-KW-006582","row_version":1,"title":"위험하게 실은 화물","original":"Dangerously Loaded Cargo","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"차량에 실은 짐이 이동 중 풀려 주변 사람과 길을 위협한다. 작은 관리 소홀이나 손상된 고정 장치가 큰 사건의 복선이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006582/index.html"},{"id":"MEJE-KW-006583","row_version":1,"title":"궤도를 떠도는 위험한 우주 잔해","original":"Dangerous Orbital Debris","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"버려진 인공 물체의 조각이 우주선이나 거주지에 위협이 되는 궤도 환경. 인간이 만든 쓰레기가 새로운 우주 장애물이 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006583/index.html"},{"id":"MEJE-KW-006584","row_version":1,"title":"섞으면 위험한 초자연 물질","original":"Dangerous Phlebotinum Interaction","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"서로 다른 마법 물질이나 에너지원을 결합하면 뜻밖의 폭주가 일어난다는 세계 규칙. 각각의 힘이 유용해도 함께 쓸 수 없다는 제한을 만든다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006584/index.html"},{"id":"MEJE-KW-006585","row_version":1,"title":"고령 운전자를 위험으로 그리는 관습","original":"Dangerous Senior Driver","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"고령 운전자는 모두 운전이 서툴고 다른 사람을 위협한다는 고정관념을 장면에 사용한다. 나이만으로 개인의 능력을 단정하는 표현으로 구분한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006585/index.html"},{"id":"MEJE-KW-006586","row_version":1,"title":"치료 중 능력이 폭주하는 환자","original":"Dangerous Super-Powered Patient","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"강한 능력을 가진 인물이 다친 상태에서 보호 반응을 제어하지 못해 돌보려는 사람까지 위험에 놓인다. 도움이 필요한 상태와 다가가기 어려운 상황이 겹친다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006586/index.html"},{"id":"MEJE-KW-006587","row_version":1,"title":"전장 안의 위험 지형","original":"Dangerous Terrain","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"싸움터의 낭떠러지나 움직이는 구조물이 양쪽 모두에게 위협이 된다. 대결은 상대뿐 아니라 주변 공간을 의식해야 한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006587/index.html"},{"id":"MEJE-KW-006588","row_version":1,"title":"위협의 통로가 된 창문","original":"Dangerous Windows","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"안전해 보이는 실내 창문이 밖의 공격자나 존재가 접근하는 경로가 된다. 유리 한 장의 경계가 무너지며 공간의 불안이 커진다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006588/index.html"},{"id":"MEJE-KW-006589","row_version":1,"title":"사고가 끊이지 않는 직장","original":"Dangerous Workplace","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"일상 업무 공간에서 큰 사고나 위험이 유난히 자주 벌어진다. 근무 자체가 생존 과제처럼 그려진다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006589/index.html"},{"id":"MEJE-KW-006590","row_version":1,"title":"훈련 장면으로 시작하는 가짜 위기","original":"Danger Room Cold Open","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"처음에는 실제 전투처럼 보였던 장면이 팀의 모의 훈련으로 밝혀진다. 짧은 시작 장면에서 각자의 능력과 협력을 함께 소개한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006590/index.html"},{"id":"MEJE-KW-006591","row_version":1,"title":"뒷좌석에 숨어 있던 위협","original":"Danger Takes a Backseat","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"차에 탄 인물이 뒤쪽에 누군가 숨어 있었다는 사실을 뒤늦게 알아챈다. 사적인 공간이라는 믿음이 갑자기 깨진다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006591/index.html"},{"id":"MEJE-KW-006592","row_version":1,"title":"얇은 얼음이 예고하는 추락","original":"Danger — Thin Ice","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"물이 덮인 곳의 얼음이 갓 얼어 약하다는 정보가 먼저 제시된다. 나중에 누군가 얼음을 밟을 때 앞선 경고가 긴장이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006592/index.html"},{"id":"MEJE-KW-006593","row_version":1,"title":"시간이 지나면 사라지는 위협","original":"Danger with a Deadline","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"적의 힘이나 활동 시간이 제한되어 있어 주인공은 직접 이기기보다 버티며 시간이 다하기를 기다린다. 위험의 끝을 아는 것이 방어 전략의 중심이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006593/index.html"},{"id":"MEJE-KW-006594","row_version":1,"title":"거인에게 대롱대롱 들리다","original":"Dangled by a Giant","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"거대한 인물이 작은 사람을 옷이나 몸의 일부로 집어 들고 공중에 매단다. 크기와 힘의 차이가 한 장면에서 드러난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006594/index.html"},{"id":"MEJE-KW-006595","row_version":1,"title":"단정한 가는 콧수염","original":"Dapper Pencil Mustache","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"입술 위에 가늘고 정교하게 다듬은 콧수염이 세련된 인상을 만든다. 짧은 털의 윤곽이 인물의 시대감과 취향을 암시한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006595/index.html"},{"id":"MEJE-KW-006596","row_version":1,"title":"정장 차림의 펭귄","original":"Dapper Penguin","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"검은색과 흰색의 깃털을 정장처럼 보고 펭귄에게 나비넥타이나 모자를 더한다. 동물이 격식 있는 신사처럼 그려진다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006596/index.html"},{"id":"MEJE-KW-006597","row_version":1,"title":"대담하게 나서라고 도전하기","original":"Dare to Be Badass","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누군가 주인공에게 기대를 넘어서는 일을 해 보라고 정면으로 자극한다. 도전의 말이 행동의 출발점이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006597/index.html"},{"id":"MEJE-KW-006598","row_version":1,"title":"악역 편의 여성 전투원","original":"Dark Action Girl","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"악역 진영에서 적극적으로 싸우는 여성 인물. 외형의 어두움보다 소속과 행동이 역할을 결정한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006598/index.html"},{"id":"MEJE-KW-006599","row_version":1,"title":"초기 중세 유럽을 암흑기로 그리기","original":"Dark Age Europe","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 초기 중세 유럽을 무질서와 무지와 불결함만 가득한 시대처럼 묘사한다. 역사적 시기 전체를 단순화한 이미지로 읽는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006599/index.html"},{"id":"MEJE-KW-006600","row_version":2,"title":"어둡게 과장한 슈퍼히어로 이름","original":"Dark Age of Supernames","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"거칠고 위협적인 인상을 내려고 슈퍼히어로에게 피와 어둠을 연상시키는 이름을 붙인다. 이름이 작품의 시대적 취향과 톤을 드러낸다. 위협적인 이름은 영웅물을 더 어둡고 거칠어진 후속 이야기 방향으로 바꾼 시대적 취향을 보여준다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006600/index.html"},{"id":"MEJE-KW-006601","row_version":1,"title":"어두운 과거가 만든 인물","original":"Dark and Troubled Past","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"과거의 큰 상처나 비극이 현재 인물의 태도와 선택에 오래 남아 있다. 사건을 말하지 않아도 행동과 복장이 그 흔적을 암시한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006601/index.html"},{"id":"MEJE-KW-006602","row_version":1,"title":"다크 카바레","original":"Dark Cabaret","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"카바레의 무대 감각에 고딕과 펑크 계열 음악의 어두운 분위기를 섞은 음악 양식. 익살스러운 공연성과 음산한 정서가 함께 들린다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006602/index.html"},{"id":"MEJE-KW-006603","row_version":1,"title":"불 꺼진 건물 안의 총격전","original":"Darkened Building Shootout","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물들이 어두운 실내에서 서로의 위치를 짐작하며 총격을 주고받는다. 빛과 소리의 짧은 단서가 긴장을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006603/index.html"},{"id":"MEJE-KW-006604","row_version":3,"title":"더 어둡고 거칠어진 후속 이야기","original":"Darker and Edgier","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기존 작품이나 시리즈의 새 이야기가 폭력과 냉소를 늘려 전체 분위기를 더 무겁게 바꾼다. 변화의 폭이 인물과 세계의 읽는 방식을 바꾼다. 원작의 분위기를 팬이 비극적으로 바꾸는 경우 밝은 원작을 어둡게 바꾼 팬 창작에서 같은 변화를 볼 수 있다. 판타지에 공포와 냉소를 강하게 더한 장르적 결과는 다크 판타지다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006604/index.html"},{"id":"MEJE-KW-006605","row_version":1,"title":"아프리카를 미지의 위험으로만 그리기","original":"Darkest Africa","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"식민지 시대 모험물의 시선이 아프리카의 다양한 지역과 사람을 하나의 신비하고 위협적인 공간으로 뭉뚱그린다. 실제 대륙의 다양성을 지우는 재현으로 구분한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006605/index.html"},{"id":"MEJE-KW-006606","row_version":1,"title":"모든 것이 무너진 최악의 순간","original":"Darkest Hour","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기 중간이나 후반에 주인공의 선택지가 거의 사라지고 희망도 보이지 않는 시점. 이후의 결단이나 반전이 이 낮은 지점에서 힘을 얻는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006606/index.html"},{"id":"MEJE-KW-006608","row_version":1,"title":"밝은 원작을 어둡게 바꾼 팬 창작","original":"Dark Fic","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"본래 가벼운 작품의 인물과 사건을 팬이 비극이나 공포가 두드러진 이야기로 다시 쓴다. 원작의 분위기를 뒤집는 해석이 창작의 중심이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006608/index.html"},{"id":"MEJE-KW-006609","row_version":1,"title":"예상을 깬 무명 배우 캐스팅","original":"Darkhorse Casting","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"큰 역할에 유명 배우 대신 대중에게 잘 알려지지 않은 배우를 기용한다. 익숙한 스타 이미지 없이 배역을 새롭게 받아들이게 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006609/index.html"},{"id":"MEJE-KW-006610","row_version":1,"title":"뒤늦게 빛나는 형제자매","original":"Dark Horse Sibling","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족 안에서 주목받지 못하던 형제자매가 뜻밖의 능력과 성과를 드러낸다. 기존의 우열 관계와 가족의 기대가 흔들린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006610/index.html"},{"id":"MEJE-KW-006611","row_version":1,"title":"두 강자를 제친 예상 밖의 승자","original":"Dark Horse Victory","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"모두가 주목한 두 경쟁자가 서로에게만 집중하는 사이 제삼의 경쟁자가 이긴다. 무시받던 인물이 판의 결과를 뒤집는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006611/index.html"},{"id":"MEJE-KW-006612","row_version":2,"title":"어둠을 악의 신호로 쓰기","original":"Dark Is Evil","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"빛이 없는 공간과 검은 색조를 악역이나 위험의 상징으로 연결한다. 익숙한 시각 약속이며 실제 어둠이나 색에 도덕적 성질이 있다는 뜻은 아니다. 어둠을 악의 표지로 쓰는 선택은 작품의 톤을 더 어둡고 거칠어진 후속 이야기 방향으로 이끌 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006612/index.html"},{"id":"MEJE-KW-006613","row_version":2,"title":"어둠의 힘을 써도 악하지 않은 존재","original":"Dark Is Not Evil","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"검은 외형이나 그림자 능력 때문에 악해 보이는 인물·종족이 실제로는 선한 선택을 한다. 색과 능력을 도덕성의 증거로 여기는 기대를 뒤집는다. 어둠을 공포의 신호로 쓰는 어둠 속에 들어가면 닥치는 위험은 어두운 외형만으로 도덕성을 판단하는 기대를 만든다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006613/index.html"}]}.cards;